import { Button } from '@refy-design/web';
import { ButtonGroup } from '@refy-design/web';
function SelectionDemo({
  orientation = 'horizontal',
  labels,
}: {
  orientation?: 'horizontal' | 'vertical';
  labels: string[];
}) {
  return (
    <ButtonGroup orientation={orientation} label="View format" defaultActiveIndex={0}>
      {labels.map((label) => (
        <Button key={label}>{label}</Button>
      ))}
    </ButtonGroup>
  );
}
export function Example() {
  return <SelectionDemo labels={['List', 'Map', 'Gallery']} />;
}

import { Button } from '@refy-design/web';
import { ButtonGroup } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof ButtonGroup>, 'orientation' | 'label'> = {
    orientation: 'horizontal',
    label: 'File actions',
  };
  return (
    <ButtonGroup {...args}>
      <Button>First</Button>
      <Button>Second</Button>
      <Button disabled>Unavailable</Button>
    </ButtonGroup>
  );
}

